import heapq
import itertools


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}  # name -> vip
        self._tickets = {}    # id -> dict
        self._next_id = 1
        self._counter = itertools.count()  # tie-breaker for FIFO within priority
        self._queue = []      # heap of (-priority_rank, counter, ticket_id)

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
        }
        self._enqueue(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "open":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        ticket["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("Cannot reopen a closed ticket")
        if ticket["status"] == "open":
            return
        ticket["status"] = "open"
        self._enqueue(ticket_id)

    # ---- helpers ----

    def _priority_rank(self, ticket_id: int) -> int:
        # Higher rank = handled first. Use negative for max-heap behavior.
        priority = self._tickets[ticket_id]["priority"]
        return -self.PRIORITIES.index(priority)

    def _enqueue(self, ticket_id: int) -> None:
        # VIP customers' tickets get priority boost, plus with earlier tickets
        # receiving priority within same base priority.
        ticket = self._tickets[ticket_id]
        vip = self._customers.get(ticket["customer"], False)
        rank = self._priority_rank(ticket_id)
        if vip:
            rank -= 1
        heapq.heappush(self._queue, (rank, next(self._counter), ticket_id))
